function formProfile(){const f=$('#setup-form'),fd=new FormData(f);const number=k=>fd.get(k)===''?'':Number(fd.get(k));const thresholdSource=String(fd.get('thresholdSource')||'auto'),manual=String(fd.get('controlledPace')||'').trim(),imported=String(fd.get('importedThresholdPace')||'').trim();return {name:String(fd.get('name')||'L\u00f8per').trim().slice(0,40),goalMode:fd.get('goalMode'),goalDistance:number('goalDistance'),goalTime:String(fd.get('goalTime')||'').trim(),raceDate:String(fd.get('raceDate')||''),startDate:String(fd.get('startDate')||''),startWeekKm:number('startWeekKm'),startWeekThreshold:number('startWeekThreshold'),startWeekLongDone:fd.has('startWeekLongDone'),weeks:number('weeks'),referenceDistance:number('referenceDistance'),referenceTime:String(fd.get('referenceTime')||'').trim(),baseKm:number('baseKm'),maxKm:number('maxKm'),growth:fd.has('growth'),days:fd.getAll('day').map(Number),longDay:number('longDay'),maxMinutes:number('maxMinutes'),recentLongMinutes:number('recentLongMinutes'),thresholdHabit:number('thresholdHabit'),control:fd.get('control'),lactateCap:number('lactateCap'),maxHr:number('maxHr'),pulseCap:number('pulseCap'),thresholdSource,importedThresholdPace:imported,importedActivityCount:Number(fd.get('importedActivityCount')||0),importedThresholdConfidence:String(fd.get('importedThresholdConfidence')||''),importedThresholdNote:String(fd.get('importedThresholdNote')||''),controlledPace:thresholdSource==='manual'?manual:thresholdSource==='imported'?imported:'',strides:fd.has('strides'),confirmed:fd.has('confirmed')};}
function weightedMedian(items){const a=items.filter(x=>Number.isFinite(x.pace)&&Number.isFinite(x.weight)&&x.weight>0).sort((x,y)=>x.pace-y.pace);const total=a.reduce((s,x)=>s+x.weight,0);let c=0;for(const x of a){c+=x.weight;if(c>=total/2)return x.pace;}return NaN;}
function parseCsvRows(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i];if(q){if(ch==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(ch==='"')q=false;else cell+=ch;}else if(ch==='"')q=true;else if(ch===','){row.push(cell);cell='';}else if(ch==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=ch;}if(cell||row.length){row.push(cell);rows.push(row);}return rows.filter(r=>r.some(v=>String(v).trim()!==''));}
function parseNum(v){if(v==null)return NaN;const x=String(v).trim().replace(/\s/g,'').replace(',','.');return Number(x);}
function parseActivityDate(v){const d=new Date(v);return Number.isFinite(d.getTime())?d:null;}
function withinLastYear(d){if(!d)return true;const age=(Date.now()-d.getTime())/86400000;return age>=-2&&age<=370;}
function currentThresholdAnchor(){try{const p=formProfile(),sp=E.speeds({...p,controlledPace:''});return {fast:sp.controlledFast,slow:sp.controlledSlow,mid:(sp.controlledFast+sp.controlledSlow)/2,p10:sp.p10};}catch{return {fast:240,slow:270,mid:255,p10:230};}}
function analyzeCsv(text){const rows=parseCsvRows(text);if(rows.length<2)return [];const headers=rows[0].map(x=>x.trim().toLowerCase());const find=(...names)=>headers.findIndex(h=>names.some(n=>h===n||h.includes(n)));const iType=find('activity type','type'),iDate=find('activity date','date'),iName=find('activity name','name'),iDist=find('distance'),iMove=find('moving time'),iElapsed=find('elapsed time');if(iDist<0||(iMove<0&&iElapsed<0))return [];const anchor=currentThresholdAnchor(),out=[];for(const r of rows.slice(1)){const type=iType>=0?String(r[iType]||'').toLowerCase():'run';if(type&&!/(run|running|trail)/.test(type))continue;const d=iDate>=0?parseActivityDate(r[iDate]):null;if(!withinLastYear(d))continue;let km=parseNum(r[iDist]);if(!Number.isFinite(km)||km<=0)continue;if(km>250)km/=1000;let sec=parseNum(r[iMove>=0?iMove:iElapsed]);if(!Number.isFinite(sec)||sec<=0)continue;if(sec<1000&&km>5)sec*=60;const pace=sec/km;if(km<4||km>30||pace<150||pace>600)continue;const eq10=sec*Math.pow(10/km,1.06),p10=eq10/10,est=p10*1.115;const name=iName>=0?String(r[iName]||'').toLowerCase():'';const race=/(race|racing|parkrun|konkurr|l\u00f8p|5k|10k|halv|half)/.test(name);if(est<anchor.fast*.9||est>anchor.slow*1.12)continue;out.push({pace:est,weight:race?3:1,kind:race?'race':'summary'});}return out;}
function textOf(el,tag){const n=el.getElementsByTagName(tag)[0];return n?Number(n.textContent):NaN;}
function analyzeTcx(text){const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))return [];const anchor=currentThresholdAnchor(),out=[];for(const act of Array.from(xml.getElementsByTagName('Activity'))){const sport=String(act.getAttribute('Sport')||'').toLowerCase();if(sport&&sport!=='running')continue;const laps=Array.from(act.getElementsByTagName('Lap'));const candidates=[];let totalSec=0,totalM=0;for(const lap of laps){const sec=textOf(lap,'TotalTimeSeconds'),m=textOf(lap,'DistanceMeters');if(!Number.isFinite(sec)||!Number.isFinite(m)||m<=0)continue;totalSec+=sec;totalM+=m;const pace=sec/(m/1000);if(sec>=180&&sec<=1200&&m>=500&&pace>=150&&pace<=anchor.slow*1.08)candidates.push(pace);}if(candidates.length>=3){const sorted=[...candidates].sort((a,b)=>a-b),med=sorted[Math.floor(sorted.length/2)],cluster=candidates.filter(x=>Math.abs(x-med)/med<=.06);if(cluster.length>=3){out.push({pace:cluster.reduce((a,b)=>a+b,0)/cluster.length,weight:4,kind:'laps'});continue;}}if(totalM>=4000&&totalSec>=900&&totalSec<=7200){const km=totalM/1000,eq10=totalSec*Math.pow(10/km,1.06),est=(eq10/10)*1.115;if(est>=anchor.fast*.9&&est<=anchor.slow*1.12)out.push({pace:est,weight:1.5,kind:'summary'});}}return out;}
async function importActivities(files){const all=[];let read=0;for(const file of files){if(file.size>20*1024*1024)continue;const text=await file.text();const name=file.name.toLowerCase();const rows=name.endsWith('.tcx')?analyzeTcx(text):name.endsWith('.csv')?analyzeCsv(text):[];all.push(...rows);read++;}if(!all.length)throw new Error('Fant ingen egnede l\u00f8pedata i filene. Denne versjonen analyserer Strava-CSV og TCX; direkte FIT-import kommer senere.');const pace=weightedMedian(all),detailed=all.filter(x=>x.kind==='laps').length,count=all.length;const confidence=detailed>=3||count>=8?'H\u00f8y':detailed>=1||count>=4?'Middels':'Lav';const note=detailed?`${detailed} \u00f8kter hadde brukbare rundedata.`:'Anslaget bygger hovedsakelig p\u00e5 aktivitetsoppsummeringer.';return {pace:E.pace(pace),count,confidence,note,read};}
function openStravaInfo(){openModal(modalHead('Strava-tilkobling','Front-end er klar, men den lokale HTML-filen kan ikke lagre Strava-hemmeligheten sikkert.')+`<div class="notice"><strong>Direkte synk er ikke aktiv enn\u00e5.</strong> Strava bruker OAuth og krever en registrert app, sikker tokenutveksling og en liten backend. N\u00e5 kan du importere en Strava-CSV eller TCX lokalt; dataene forlater ikke nettleseren.</div><p class="subtle" style="margin-top:15px">N\u00e5r appen publiseres, kan samme terskelanalyse kobles til aktivitetsstr\u00f8mmene fra Strava slik at estimatet oppdateres automatisk.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Lukk</button><button class="btn" id="modal-activity-import">Importer treningsdata</button></div>`);$('#modal-activity-import').addEventListener('click',()=>{closeModal();$('#activity-file').click();},{once:true});}
function bindSetup(){const form=$('#setup-form');form.addEventListener('input',updatePreview);form.addEventListener('change',updatePreview);form.addEventListener('submit',e=>{e.preventDefault();const p=formProfile(),errors=E.validate(p);const box=$('#setup-errors');if(errors.length){box.innerHTML='<strong>Disse feltene trenger en sjekk:</strong><ul>'+errors.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>';box.classList.remove('hidden');box.focus();box.scrollIntoView({block:'center'});return;}if(state.plan){confirmDialog('Bytte ut ukeplanen?','Den eksisterende planen erstattes. Dine registrerte \u00f8kter bevares. En sikkerhetskopi bevarer ogs\u00e5 den gamle planen.','Lag ny plan',()=>createPlan(p));}else createPlan(p);});updatePreview();}
function createPlan(p){try{state.plan=E.generate(p);state.profile=p;weekIndex=0;persist();closeModal();navigate('plan');toast('Planen er laget. Alle \u00f8kter er forel\u00f8pig planlagt, ikke gjennomf\u00f8rt.');}catch(e){toast(e.message);}}
