function stat(label,n,unit,foot,icon){return `<section class="stat-card"><div class="stat-top"><span>${label}</span>${ic(icon)}</div><div class="stat-num">${n}<small>${unit}</small></div><div class="stat-foot">${foot}</div></section>`;}
function sessionRow(s,ds,d){const isToday=ds===E.today(),beforeStart=ds<state.plan.profile.startDate&&weekIndex===0;if(beforeStart)return `<div class="session rest ${isToday?'today':''}"><div><div class="session-day">${DS[d]}</div><div class="session-date">${E.date(ds).getDate()}</div></div><div><div class="session-title">F\u00f8r planstart</div><div class="session-sub">${Number(state.plan.profile.startWeekKm||0)>0?'Tidligere trening er oppsummert i startuka.':'Planen begynner senere denne uka.'}</div></div><div>${ic('clock')}</div></div>`;if(!s||s.type==='rest')return `<div class="session rest ${isToday?'today':''}"><div><div class="session-day">${DS[d]}</div><div class="session-date">${E.date(ds).getDate()}</div></div><div><div class="session-title">${esc(s?.title||'Hvile / fri')}</div><div class="session-sub">${state.plan.profile.goalMode==='time'&&ds>state.plan.profile.raceDate?'Etter konkurransen \u2013 vurder restitusjon individuelt.':'Ingen l\u00f8pe\u00f8kt planlagt.'}</div></div><div>${ic('leaf')}</div></div>`;
 const log=state.logs.find(l=>l.sessionId===s.id),status=log?(log.status==='done'?'Logget':'Hoppet over'):'Planlagt',p=state.plan.profile,pulse=pulseGuidance(s,p);
 const data=s.type==='easy'||s.type==='long'?`<strong>${num(s.minutes)} min</strong><span>ca. ${num(s.km)} km</span>`:`<strong>${num(s.km)} km</strong><span>ca. ${num(s.minutes)} min</span>`;
 return `<button type="button" class="session ${s.type} ${isToday?'today':''}" data-session="${esc(s.id)}"><div><div class="session-day">${DS[d]}</div><div class="session-date">${E.date(ds).getDate()}</div></div><div><div class="session-title">${esc(s.title)}</div><div class="session-sub">${s.type==='threshold'?`${s.restSeconds} sek pause \u00b7 `:s.type==='race'?'Med opp-/nedjogg \u00b7 ':''}${pulse?pulse+' \u00b7 ':''}${status}${log?.status==='done'?' \u2713':''}</div></div><div class="session-data">${data}</div></button>`;
}
function planChart(plan,idx){const max=Math.max(...plan.weeks.map(w=>w.km),1);return `<div class="week-chart" role="group" aria-label="Planlagt ukesmengde">${plan.weeks.map((w,i)=>`<button type="button" data-week="${i}" aria-label="Uke ${i+1}: ${num(w.km)} km, ${w.phase}" title="Uke ${i+1}: ${num(w.km)} km"><span class="bar ${i===idx?'active':''} ${w.phase==='Konkurranseuke'?'race':''}" style="height:${Math.max(4,w.km/max*82)}px"><span class="bar-work" style="height:${100-w.easyPercent}%"></span></span><span class="barlabel">${i+1}</span></button>`).join('')}</div><div class="chart-legend"><span>Uke 1</span><span>${plan.weeks.length} uker \u00b7 trykk for detaljer</span></div>`;}
function renderLogs(){
 const logs=[...state.logs].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
 return pageHead('Treningen som faktisk ble gjort','Sm\u00e5 notater. Bedre oversikt.','Logg mengde, innsats og eventuelle laktatm\u00e5linger. Ingenting fylles inn som gjennomf\u00f8rt automatisk.')+`
 <div class="toolbar"><div class="btn-group"><button class="btn" data-action="new-log">${ic('plus')} Registrer \u00f8kt</button></div><div class="btn-group"><button class="btn outline" data-action="export">${ic('download')} Sikkerhetskopi</button><button class="btn outline" data-action="import">${ic('upload')} Gjenopprett</button></div></div>
 <section class="card">${logs.length?`<div class="card-title"><h2>${logs.length} registrering${logs.length===1?'':'er'}</h2><span class="tag green">Bare dine data</span></div><div class="logs-table-wrap"><table class="logs-table"><thead><tr><th>Dato / \u00f8kt</th><th>Mengde</th><th class="log-hide-mobile">Fart</th><th>Innsats</th><th class="log-hide-mobile">Dagsform</th><th><span class="tiny">Endre</span></th></tr></thead><tbody>${logs.map(l=>`<tr><td><div class="log-main">${shortDate(l.date)} ${E.date(l.date).getFullYear()}</div><div class="log-secondary">${TYPES[l.type]||'L\u00f8ping'}${l.status==='skipped'?' \u00b7 Hoppet over':''}</div>${l.note?`<div class="log-secondary" title="${esc(l.note)}">${esc(l.note.slice(0,60))}${l.note.length>60?'\u2026':''}</div>`:''}</td><td><strong>${l.status==='done'?num(l.km)+' km':'\u2014'}</strong><div class="log-secondary">${l.status==='done'?E.time(l.seconds):'Ikke regnet med'}</div></td><td class="log-hide-mobile">${l.status==='done'&&l.km>0?E.pace(l.seconds/l.km)+'/km':'\u2014'}</td><td>${l.status==='done'?l.rpe+'/10':'\u2014'}${l.samples?.length?`<div class="log-secondary">${l.samples.length} m\u00e5linger</div>`:''}</td><td class="log-hide-mobile"><span class="tag ${['sick','pain'].includes(l.feeling)?'red':l.feeling==='tired'?'orange':'gray'}">${FEELINGS[l.feeling]}</span></td><td><div class="log-actions"><button class="icon-btn" data-edit-log="${esc(l.id)}" aria-label="Rediger \u00f8kten ${shortDate(l.date)}">${ic('edit')}</button><button class="icon-btn" data-delete-log="${esc(l.id)}" aria-label="Slett \u00f8kten ${shortDate(l.date)}">${ic('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Historikken starter her.','Ingen eksempel\u00f8kter eller oppdiktede kilometer. Registrer din f\u00f8rste tur n\u00e5r den er gjennomf\u00f8rt.',`<button class="btn light" data-action="new-log">${ic('plus')} Min f\u00f8rste \u00f8kt</button>`)}</section>
 <div class="notice" style="margin-top:20px">Loggen lagres bare i denne nettleseren. Bruk sikkerhetskopi for \u00e5 flytte data til en annen enhet. Sletting av nettleserdata kan ogs\u00e5 slette treningshistorikken.</div>`;
}
function renderProgress(){const done=state.logs.filter(l=>l.status==='done'),total=done.reduce((a,l)=>a+l.km,0),minutes=done.reduce((a,l)=>a+l.seconds/60,0),thisMonday=E.monday(E.today());const weeks=Array.from({length:8},(_,i)=>{const start=E.addDays(thisMonday,(i-7)*7);const values=done.filter(l=>l.date>=start&&l.date<=E.addDays(start,6));return {start,km:values.reduce((a,l)=>a+l.km,0),n:values.length};});const max=Math.max(...weeks.map(w=>w.km),1);const avg=done.length?done.reduce((a,l)=>a+l.rpe,0)/done.length:0;return pageHead('Se tilbake. Juster framover.','Kontinuiteten blir synlig.','Dette er registrert trening \u2013 ikke prognoser, formpoeng eller antatte forbedringer.')+`
 <div class="overview-stats">${stat('Totalt registrert',num(total),'km','Alle gjennomf\u00f8rte \u00f8kter','chart')}${stat('Gjennomf\u00f8rte \u00f8kter',done.length,'', 'Hoppet over teller ikke','check')}${stat('Samlet l\u00f8petid',num(minutes/60),'timer','Basert p\u00e5 din registrering','clock')}${stat('Gjennomsnittlig innsats',done.length?num(avg):'\u2014','/10','En beskrivelse, ikke et formm\u00e5l','heart')}</div>
 <div class="grid equal-col"><section class="card"><div class="card-title"><h2>De siste \u00e5tte ukene</h2><span class="tag gray">Logget km</span></div>${done.length?`<div class="trend-chart" aria-label="Registrert distanse per uke">${weeks.map(w=>`<div class="trend-column" title="Uke fra ${shortDate(w.start)}: ${num(w.km)} km"><span class="trend-number">${num(w.km)}</span><div class="trend-bar" style="height:${Math.max(2,w.km/max*125)}px"></div><span class="trend-date">${shortDate(w.start)}</span></div>`).join('')}</div>`:empty('Ingen data \u00e5 tegne enn\u00e5','S\u00f8ylene dukker opp etter din f\u00f8rste registrerte \u00f8kt.')}<p class="tiny muted" style="margin:20px 0 0">S\u00f8ylene viser kalenderuker fra mandag. Innev\u00e6rende uke kan v\u00e6re ufullstendig.</p></section>
 <section class="card"><div class="card-title"><h2>Fartskalkulator</h2><span class="tag gray">Bare regning</span></div><form id="calc-form" class="pace-calculator"><div class="field"><label for="calc-distance">Distanse (km)</label><input id="calc-distance" type="number" min="0.1" max="200" step="0.1" value="10" inputmode="decimal"></div><div class="field"><label for="calc-time">Tid (mm:ss / t:mm:ss)</label><input id="calc-time" value="38:00" maxlength="10"></div><div class="calc-output" id="calc-output" aria-live="polite"></div></form><p class="tiny muted" style="margin:16px 0 0">Kalkulatoren endrer ikke treningsfarten i planen. 38:00 er en redigerbar eksempelverdi.</p></section></div>
 <section class="card" style="margin-top:22px"><h2>Hva sier m\u00e5lingene?</h2><p class="subtle" style="margin-bottom:0">Du finner laktat, puls og fart per drag ved \u00e5 redigere en logget \u00f8kt. Denne versjonen beregner ikke en terskelkurve eller ny konkurranseprognose fra m\u00e5lingene. Sammenlign bare \u00f8kter under tilstrekkelig like forhold.</p></section>`;}
function bindCalculator(){const update=()=>{const km=Number($('#calc-distance').value),s=E.parseTime($('#calc-time').value);$('#calc-output').innerHTML=km>0&&Number.isFinite(s)&&s>0?`<span>Gjennomsnittsfart<br><span class="tiny muted">${num(km/s*3600)} km/t</span></span><strong>${E.pace(s/km)} <span class="small">/km</span></strong>`:'Oppgi en gyldig distanse og tid.';};$('#calc-form').addEventListener('submit',e=>e.preventDefault());$('#calc-form').addEventListener('input',update);update();}
function renderModel(){return pageHead('Bak planen','Prinsipper, ikke en elitekopi.','En uavhengig, regelbasert planlegger inspirert av Marius Bakkens beskrivelser.')+`
 <div class="grid equal-col"><section class="card"><div class="card-title"><h2>Dette tar vi med</h2><span class="tag green">Kildegrunnlag</span></div><div class="rules">
 <div class="rule"><div><h3>Kontrollert arbeid rundt egen terskel</h3><p>Bakken beskriver intervaller med n\u00f8ye styrt intensitet og mye rolig l\u00f8ping. Laktatverdiene er individuelle; en universell 4 mmol/l-grense er ikke et godt grunnlag for alle. <a href="https://www.mariusbakken.com/the-norwegian-model.html" target="_blank" rel="noopener noreferrer">[1]</a></p></div></div>
 <div class="rule"><div><h3>Kontroll fra flere signaler</h3><p>I sin utdyping beskriver Bakken puls, snakketest og opplevd innsats som kryssjekker n\u00e5r laktat ikke m\u00e5les. Ved motstridende signaler trengs lavere fart og st\u00f8rre margin. <a href="https://www.mariusbakken.com/double-threshold-training.html" target="_blank" rel="noopener noreferrer">[2]</a></p></div></div>
 <div class="rule"><div><h3>Ikke bare dobbel terskel</h3><p>Originalen beskriver ogs\u00e5 doble terskeldager og ekstra arbeid over terskel hos elitel\u00f8pere. Her brukes f\u00e6rre enkelt\u00f8kter. Det er en tilpasning, ikke hele originalmodellen. <a href="https://www.mariusbakken.com/the-norwegian-model.html" target="_blank" rel="noopener noreferrer">[1]</a></p></div></div>
 <div class="rule"><div><h3>Ingen dokumentert garanti</h3><p>Beskrivelsene og oversiktsartikkelen om modellen dokumenterer ikke at denne appens opplegg er optimalt, trygt for alle eller bedre enn andre opplegg. <a href="https://pubmed.ncbi.nlm.nih.gov/36900796/" target="_blank" rel="noopener noreferrer">[3]</a></p></div></div>
 </div></section>
 <section class="card"><div class="card-title"><h2>Dette er appens egne valg</h2><span class="tag orange">Ikke Bakkens regler</span></div><div class="rules">
 <div class="rule"><div><h3>0\u20132 kontrollerte \u00f8kter</h3><p>Mengde, valgte dager og tidligere terskelvaner begrenser dosen. Ved minst 40 km, fem dager og to innarbeidede \u00f8kter kan planen ha to. Uten terskelvane er de f\u00f8rste to ukene rolige. Dette er programmerte valg, ikke validerte grenser.</p></div></div>
 <div class="rule"><div><h3>Stabil mengde, lettere uker</h3><p>En full f\u00f8rste uke starter p\u00e5 95 % av oppgitt normalmengde. Starter planen midt i uka, skaleres den ned etter dagene som gjenst\u00e5r og det du oppgir at du allerede har gjort. Hver fjerde ordin\u00e6re uke er lettere (80 %). Frivillig vekst er 3 prosentpoeng av normalmengden per byggeuke, maksimalt 20 % i blokken. Siste del f\u00f8r l\u00f8pet reduseres. Dette er enkle planleggingsregler, ikke medisinske sikkerhetsgrenser.</p></div></div>
 <div class="rule"><div><h3>Den lengre turen planlegges f\u00f8rst</h3><p>Varigheten du faktisk har t\u00e5lt den siste m\u00e5neden brukes som anker. I vanlige uker reserveres den lengre turen f\u00f8r resten av de rolige kilometerne fordeles, med tak fra ukesmengde og oppgitt tid per \u00f8kt. I en kort startuke kan en terskel\u00f8kt falle bort for \u00e5 bevare den lengre turen. En for kort rest\u00f8kt merkes som vanlig rolig tur, ikke som lengre tur. Dette er appens planleggingsregel.</p></div></div>
 <div class="rule"><div><h3>Rolige turer styres etter minutter</h3><p>For rolige turer og den lengre turen er planlagt tid hovedresepten. Kilometer vises bare som et omtrentlig resultat av en veiledende fart. Dagsform, terreng, vind og varme skal kunne endre farten uten at du har bommet p\u00e5 \u00f8kten.</p></div></div>
 <div class="rule"><div><h3>Olympiatoppens pulssoner er valgfrie</h3><p>N\u00e5r makspuls er lagt inn, viser appen Olympiatoppens I-1 til I-5 som slag per minutt: I-1 55\u201372 %, I-2 72\u201382 %, I-3 82\u201387 %, I-4 87\u201392 % og I-5 over 92 % av HFmaks. Rolige turer merkes I-1. Kontrollerte intervaller f\u00e5r I-3 som pulsst\u00f8tte, men puls skal ikke jages opp p\u00e5 drag fordi responsen er forsinket. <a href="https://olt-skala.nif.no/" target="_blank" rel="noopener noreferrer">[4]</a></p></div></div>
 <div class="rule"><div><h3>M\u00e5let styrer retning \u2013 ikke treningsfart</h3><p>Distansen p\u00e5virker draglengde og rammen for den lengre turen. Konkurransedatoen styrer blokklengde og reduksjonen f\u00f8r l\u00f8pet. En lavere \u00f8nsket sluttid gj\u00f8r ikke treningsdragene raskere.</p></div></div>
 <div class="rule"><div><h3>Ukesjekk krever godkjenning</h3><p>To loggede \u00f8kter er minste datagrunnlag. Under 70 % av planlagt mengde, innsats p\u00e5 8/10 p\u00e5 terskel, flere tunge dager eller laktat over egen grense gir reduksjonsforslag. Dette er enkle varsler, ikke en trenervurdering.</p></div></div>
 </div><details class="details"><summary>Slik regner fartsmotoren</summary><p>En referansetid omregnes til 10 km med formelen: tid \u00d7 (10 / referansedistanse)<sup>1,06</sup>. Anslaget for kontrollert fart er 8\u201315 % langsommere per km; rolig fart er 30\u201355 % langsommere. For rolige turer brukes dette bare til \u00e5 ansl\u00e5 kilometer og totalbelastning; selve resepten vises i minutter. Dette er et grovt startanslag, ikke en m\u00e5ling av LT1/LT2 eller en validert forskrivning. Innsats og dagsform overstyrer fart.</p></details></section>
 <section class="card"><div class="card-title"><h2>Kilder og avgrensninger</h2></div><div class="sources"><article><a href="https://www.mariusbakken.com/the-norwegian-model.html" target="_blank" rel="noopener noreferrer">1. Marius Bakken: The Norwegian Model (2022) \u2197</a><p>Brukerens referanse. En erfaringsbasert beskrivelse, ikke en kontrollert studie av et treningsprogram for mosjonister.</p></article><article><a href="https://www.mariusbakken.com/double-threshold-training.html" target="_blank" rel="noopener noreferrer">2. Bakken: Double Threshold Training in Depth \u2197</a><p>Utdyping med praktiske intensitetssignaler. Forfatterens fysiologiske forklaringer er ikke alle etablerte \u00e5rsaksfunn.</p></article><article><a href="https://pubmed.ncbi.nlm.nih.gov/36900796/" target="_blank" rel="noopener noreferrer">3. Casado, Foster, Bakken & Tjelta (2023) \u2197</a><p>Oversiktsartikkel om laktatstyrte terskelintervaller. DOI: 10.3390/ijerph20053782.</p></article><article><a href="https://www.mariusbakken.com/norwegian-model-revisited.html" target="_blank" rel="noopener noreferrer">Bakken: The Norwegian Model Revisited (2025) \u2197</a><p>Oppf\u00f8lgende beskrivelse av modellens utvikling.</p></article><article><a href="https://olt-skala.nif.no/" target="_blank" rel="noopener noreferrer">4. Olympiatoppen: Intensitetsskala \u2197</a><p>Gjeldende 8-delt intensitetsskala med pulsgrenser for I-1 til I-5 og veiledning om bruk av puls, RPE, pust og andre styringsverkt\u00f8y.</p></article></div><p class="tiny muted" style="margin-top:12px">Kildene ble kontrollert 24. september 2026. De er ikke en godkjenning av Terskel.</p></section>
 <section class="card"><h2>Dataene dine og mobilbruk</h2><div class="guide-list"><div class="guide-item"><div class="guide-icon">${ic('shield')}</div><div><strong>Lokalt, uten konto</strong><p>Profil, plan og logg lagres i nettleseren. Ingen server eller datadeling er innebygd. Importert CSV/TCX analyseres lokalt i nettleseren og selve aktivitetsfilene lagres ikke av appen. En annen nettleser eller nettadresse har sin egen lagring.</p></div></div><div class="guide-item"><div class="guide-icon">${ic('download')}</div><div><strong>En sikkerhetskopi bevarer alt</strong><p>Eksportfilen inneholder profil, plan og logg. Oppbevar den privat. Ved import erstattes den lokale tilstanden f\u00f8rst etter bekreftelse.</p></div></div><div class="guide-item"><div class="guide-icon">${ic('info')}</div><div><strong>Telefon: bruk den publiserte appen</strong><p>Den publiserte HTTPS-versjonen kan legges til p\u00e5 hjemskjermen og brukes som en enkel PWA. Ta fortsatt sikkerhetskopi f\u00f8r st\u00f8rre oppdateringer.</p></div></div></div><details class="details"><summary>Hva denne versjonen ikke gj\u00f8r</summary><p>Ingen GPS-sporing eller direkte Garmin-/Strava-synkronisering enn\u00e5. Lokal analyse av Strava-CSV og TCX er tilgjengelig; FIT-import, bakgrunnsvarsler, diagnostikk og automatisk AI-coaching er ikke st\u00f8ttet. Dobbel terskel, maraton og rehabilitering er ikke st\u00f8ttet. En sykdoms- eller smerteregistrering kan bare gi et varsel og pauseforslag, ikke klarering for trening.</p></details><div class="toolbar" style="margin:22px 0 0"><button class="btn light" data-action="export">${ic('download')} Ta sikkerhetskopi</button><button class="btn outline" data-action="import">${ic('upload')} Gjenopprett</button></div></section></div>`;}
function openModal(html){if($('#modal').open)$('#modal').close();$('#modal-content').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function modalHead(title,sub=''){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" type="button" data-action="close-modal" aria-label="Lukk">${ic('close')}</button></div>`;}
function confirmDialog(title,text,button,callback){openModal(modalHead(esc(title))+`<p class="subtle">${esc(text)}</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Avbryt</button><button class="btn" id="confirm-action">${esc(button)}</button></div>`);$('#confirm-action').addEventListener('click',()=>{closeModal();callback();},{once:true});}
function findSession(id){return state.plan?.weeks.flatMap(w=>w.sessions).find(s=>s.id===id);}
function openSession(id){
 const s=findSession(id);if(!s)return;const p=state.plan.profile;const l=state.logs.find(l=>l.sessionId===id);const canLog=s.date<=E.today();
 let blocks='';
 const easyPulse=p.maxHr?zoneText(1,p.maxHr):'',workPulse=p.maxHr?zoneText(3,p.maxHr):'';
 if(s.type==='threshold'){blocks=`<div class="workout-block"><span>01 \u00b7 Oppvarming${easyPulse?`<br><span class=\"tiny\">Anbefalt puls: ${easyPulse}</span>`:''}</span><strong>${s.warmMinutes} min rolig</strong></div><div class="workout-block work"><span>02 \u00b7 Kontrollerte drag<br><span class="tiny">${s.restSeconds} sek rolig mellom dragene${workPulse?` \u00b7 Anbefalt puls: ${workPulse}`:''}${p.pulseCap?` \u00b7 Din \u00f8vre pulsgrense: ${p.pulseCap}`:''}</span></span><strong>${s.reps} \u00d7 ${s.repMinutes} min</strong></div><div class="workout-block"><span>03 \u00b7 Nedjogg${easyPulse?`<br><span class=\"tiny\">Anbefalt puls: ${easyPulse}</span>`:''}</span><strong>${s.coolMinutes} min rolig</strong></div>`;}
 else if(s.type==='race'){blocks=`<div class="workout-block"><span>Oppvarming${easyPulse?`<br><span class=\"tiny\">Anbefalt puls: ${easyPulse}</span>`:''}</span><strong>${s.warmMinutes} min rolig</strong></div><div class="workout-block work"><span>Konkurranse \u00b7 ${distanceLabel(s.raceKm)}<br><span class="tiny">Ingen fast anbefalt pulssone \u2013 styr etter l\u00f8psinnsats</span></span><strong>M\u00e5l ${p.goalTime}</strong></div><div class="workout-block"><span>Nedjogg etter behov${easyPulse?`<br><span class=\"tiny\">Anbefalt puls: ${easyPulse}</span>`:''}</span><strong>${s.coolMinutes} min</strong></div>`;}
 else blocks=`<div class="workout-block"><span>Rolig l\u00f8ping${easyPulse?`<br><span class=\"tiny\">Anbefalt puls: ${easyPulse}</span>`:''}</span><strong>${num(s.minutes)} min</strong></div>`;
 const easyFirst=s.type==='easy'||s.type==='long',zone= p.maxHr&&s.zone?zoneFor(s.zone,p.maxHr):null;
 openModal(modalHead(esc(s.title),easyFirst?`${longDate(s.date,true)} \u00b7 ${num(s.minutes)} min \u00b7 ca. ${num(s.km)} km`:`${longDate(s.date,true)} \u00b7 ca. ${num(s.km)} km / ${num(s.minutes)} min`)+`
 <span class="tag ${s.type==='threshold'?'orange':s.type==='race'?'red':'green'}">${TYPES[s.type]}</span><div class="workout-blocks">${blocks}</div>
 ${zone?`<div class="pace-box"><div><div class="pace-label">${s.type==='threshold'?'Anbefalt puls \u2013 arbeidsdrag':'Anbefalt puls \u2013 hele \u00f8kten'} \u00b7 ${zone.label}</div><div class="pace-sub">${zone.pct} av HFmaks \u00b7 ${esc(zone.breath)}</div></div><div class="pace-value">${zone.low}\u2013${zone.high}<small> slag/min</small></div></div>`:''}
 <div class="pace-box"><div><div class="pace-label">${s.type==='race'?'M\u00e5lfart, ikke prognose':easyFirst?'Fart er sekund\u00e6rt':'Veiledende fart'}</div><div class="pace-sub">${s.effort}</div></div><div class="pace-value">${paceRange(s.paceFast,s.paceSlow)}<small>${s.paceFast?' /km':''}</small></div></div>
 <div class="notice" style="margin-top:16px">${esc(s.intensity)}${easyFirst?' Styr f\u00f8rst etter planlagt tid og lett innsats; farten tilpasses dagsform og forhold.':''}</div>
 ${s.type==='threshold'&&p.control==='lactate'?`<div class="notice warn" style="margin-top:12px">Din avklarte \u00f8vre treningsgrense er ${num(p.lactateCap)} mmol/l. Noter m\u00e5linger per drag. Lav laktat alene er ikke en oppfordring til \u00e5 \u00f8ke farten; vurder ogs\u00e5 innsats og dagsform.</div>`:''}
 <p class="tiny muted" style="margin:15px 0 0">${s.type==='threshold'?'Kilometer inkluderer oppvarming, drag, pauser og nedjogg. Puls er et st\u00f8ttesignal, ikke noe du skal jage p\u00e5 dragene. ':easyFirst?'Minuttene er selve resepten for denne rolige turen. Kilometer er bare et anslag fra veiledende fart. ':'Dette er en planlagt \u00f8kt. '} </p>
 <div class="modal-actions"><button class="btn outline" data-action="close-modal">Lukk</button><button class="btn" id="session-log" ${canLog||l?'':'disabled'}>${ic(l?'edit':'plus')}${l?'Se / rediger logg':canLog?'Logg resultatet':'Logges etter gjennomf\u00f8ring'}</button></div>`);
 $('#session-log').addEventListener('click',()=>openLog(l?.id||null,s));
}
function openLog(id=null,session=null){
 const old=id?state.logs.find(l=>l.id===id):null;logContext={id:old?.id||null,sessionId:old?.sessionId||session?.id||null};
 const l=old||{date:session&&session.date<=E.today()?session.date:E.today(),type:session?.type==='rest'?'easy':session?.type||'easy',status:'done',km:'',seconds:0,rpe:'',feeling:'normal',note:'',samples:[]};
 const plannedPulse=session&&state.plan?.profile?.maxHr?pulseGuidance(session,state.plan.profile):'';
 openModal(modalHead(old?'Rediger \u00f8kten':'Hvordan gikk turen?',session?`Planlagt: ${esc(session.title)} \u00b7 ${(session.type==='easy'||session.type==='long')?num(session.minutes)+' min \u00b7 ca. '+num(session.km)+' km':'ca. '+num(session.km)+' km'}`:'Bare det du registrerer her teller som gjennomf\u00f8rt.')+`${plannedPulse?`<div class="notice" style="margin-bottom:16px"><strong>${esc(plannedPulse)}</strong></div>`:''}
 <form id="log-form" novalidate><div id="log-errors" class="notice error hidden form-error" role="alert" tabindex="-1"></div><div class="fields">
 ${inputField('log-date','Dato',l.date,'date',`max="${E.today()}"`)}
 ${selectField('log-type','\u00d8kttype',l.type,Object.entries(TYPES).filter(([k])=>k!=='rest'))}
 <div class="field full"><span class="label">Status</span><div class="choice-row"><label class="choice"><input type="radio" name="log-status" value="done" ${l.status==='done'?'checked':''}><span>Gjennomf\u00f8rt</span></label><label class="choice"><input type="radio" name="log-status" value="skipped" ${l.status==='skipped'?'checked':''}><span>Hoppet over</span></label></div></div>
 <div class="field actual-field"><label for="log-km">Faktisk distanse (km)</label><input id="log-km" name="log-km" type="number" min="0.1" max="200" step="0.01" inputmode="decimal" value="${esc(l.km)}" placeholder="Fyll inn faktisk distanse"></div>
 <div class="field actual-field"><label for="log-time">Faktisk varighet</label><input id="log-time" name="log-time" value="${l.seconds?E.time(l.seconds):''}" placeholder="mm:ss eller t:mm:ss" maxlength="10"></div>
 <div class="field actual-field"><label for="log-rpe">Opplevd innsats, 0\u201310</label><select id="log-rpe" name="log-rpe"><option value="">Velg innsats</option>${Array.from({length:11},(_,i)=>`<option value="${i}" ${l.rpe===i?'selected':''}>${i}${i===0?' \u2013 ingen anstrengelse':i===2?' \u2013 lett':i===5?' \u2013 kontrollert, merkbart':i===8?' \u2013 sv\u00e6rt hardt':i===10?' \u2013 maksimalt':''}</option>`).join('')}</select><div class="help">For intervaller: vurder arbeidsdragene. For rolige turer: vurder turen som helhet.</div></div>
 ${selectField('log-feeling','Dagsform',l.feeling,Object.entries(FEELINGS))}
 <div class="field full"><label for="log-note">Notat (valgfritt)</label><textarea id="log-note" name="log-note" maxlength="2000" placeholder="For eksempel f\u00f8lelse, underlag og forhold">${esc(l.note)}</textarea></div></div>
 <section class="sample-section actual-field"><h3>M\u00e5linger per drag <span class="tiny muted">\u00b7 valgfritt</span></h3><p class="tiny muted">Fyll inn bare det du har m\u00e5lt. Verdier blir aldri ansl\u00e5tt.</p><div class="sample-head"><span>Drag</span><span>mmol/l</span><span>Puls</span><span>Fart/km</span><span></span></div><div id="samples">${l.samples.map(sampleRow).join('')}</div><button type="button" class="btn light small" id="add-sample">${ic('plus')} Legg til m\u00e5ling</button></section>
 <div class="modal-actions"><button type="button" class="btn outline" data-action="close-modal">Avbryt</button><button class="btn" type="submit">${ic('check')} Lagre registreringen</button></div></form>`);
 const update=()=>{$$('.actual-field').forEach(el=>el.classList.toggle('hidden',new FormData($('#log-form')).get('log-status')==='skipped'));};
 $('#log-form').addEventListener('change',update);update();
 $('#add-sample').addEventListener('click',()=>{if($$('#samples .sample-row').length>=40){toast('Maksimalt 40 m\u00e5linger per \u00f8kt.');return;}$('#samples').insertAdjacentHTML('beforeend',sampleRow({rep:$$('#samples .sample-row').length+1}));});
 $('#log-form').addEventListener('submit',saveLog);
}
function sampleRow(s={}){return `<div class="sample-row"><input type="number" class="sample-rep" min="1" max="200" value="${esc(s.rep||'')}" aria-label="Dragnummer"><input type="number" class="sample-lactate" min="0" max="30" step="0.1" value="${esc(s.lactate??'')}" placeholder="\u2014" aria-label="Laktat i mmol per liter"><input type="number" class="sample-hr" min="30" max="240" value="${esc(s.hr??'')}" placeholder="\u2014" aria-label="Puls"><input type="text" class="sample-pace" value="${esc(s.pace||'')}" placeholder="m:ss" maxlength="6" aria-label="Fart per kilometer"><button class="remove-sample" type="button" aria-label="Fjern m\u00e5ling">\u00d7</button></div>`;}
function saveLog(event){
 event.preventDefault();const fd=new FormData($('#log-form'));const status=fd.get('log-status'),errors=[];
 const date=String(fd.get('log-date')),type=fd.get('log-type'),km=status==='done'?Number(fd.get('log-km')):0,seconds=status==='done'?E.parseTime(String(fd.get('log-time'))):0,rpe=status==='done'?Number(fd.get('log-rpe')):0,feeling=fd.get('log-feeling');
 if(!E.validDate(date)||date>E.today()||date<'2000-01-01')errors.push('Velg en faktisk dato fra \u00e5r 2000 til og med i dag.');
 if(!['easy','long','threshold','race'].includes(type))errors.push('Velg en gyldig \u00f8kttype.');
 if(status==='done'){
  if(!Number.isFinite(km)||km<=0||km>200)errors.push('Oppgi faktisk distanse, 0,1\u2013200 km.');
  if(!Number.isFinite(seconds)||seconds<30||seconds>86400)errors.push('Oppgi gyldig varighet som mm:ss eller t:mm:ss.');
  if(fd.get('log-rpe')===''||!Number.isInteger(rpe)||rpe<0||rpe>10)errors.push('Velg opplevd innsats fra 0 til 10.');
 }
 const samples=[];
 if(status==='done')$$('#samples .sample-row').forEach((row,i)=>{
  const value=sel=>row.querySelector(sel).value,rep=Number(value('.sample-rep')),lac=value('.sample-lactate'),hr=value('.sample-hr'),pace=value('.sample-pace');
  if(lac===''&&hr===''&&pace==='')return;
  if(!Number.isInteger(rep)||rep<1||rep>200)errors.push(`M\u00e5ling ${i+1}: oppgi dragnummer.`);
  if(lac!==''&&(!Number.isFinite(Number(lac))||Number(lac)<0||Number(lac)>30))errors.push(`M\u00e5ling ${i+1}: ugyldig laktatverdi.`);
  if(hr!==''&&(!Number.isInteger(Number(hr))||Number(hr)<30||Number(hr)>240))errors.push(`M\u00e5ling ${i+1}: ugyldig puls.`);
  if(pace!==''&&(!Number.isFinite(E.parseTime(pace))||E.parseTime(pace)<120||E.parseTime(pace)>1200))errors.push(`M\u00e5ling ${i+1}: fart m\u00e5 v\u00e6re mm:ss/km.`);
  samples.push({rep,lactate:lac===''?null:Number(lac),hr:hr===''?null:Number(hr),pace});
 });
 if(errors.length){$('#log-errors').innerHTML=errors.map(esc).join('<br>');$('#log-errors').classList.remove('hidden');$('#log-errors').focus();return;}
 const old=state.logs.find(l=>l.id===logContext.id),linked=logContext.sessionId?state.logs.find(l=>l.sessionId===logContext.sessionId):null;
 const record={id:old?.id||linked?.id||('l'+Date.now()+'-'+Math.random().toString(36).slice(2,8)),sessionId:logContext.sessionId,date,type,status,km,seconds,rpe,feeling,note:String(fd.get('log-note')||'').trim().slice(0,2000),samples,createdAt:old?.createdAt||new Date().toISOString()};
 state.logs=state.logs.filter(l=>l.id!==record.id);state.logs.push(record);persist();closeModal();render();
 if(['sick','pain'].includes(feeling)){openModal(modalHead('Ta signalet p\u00e5 alvor')+`<div class="notice warn">Registreringen er lagret. Sett intervalltrening og progresjon p\u00e5 pause ved sykdom eller smerter. Appen kan ikke vurdere \u00e5rsak eller gi klarering for trening. Ved vedvarende plager b\u00f8r du r\u00e5df\u00f8re deg med kvalifisert helsepersonell.</div><p class="subtle" style="margin:17px 0 0">Bruk ukesjekken for \u00e5 sette en kommende uke p\u00e5 pause. Ingen endring skjer uten godkjenning.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Lukk</button></div>`);}
 else toast(status==='done'?'\u00d8kten er lagret som gjennomf\u00f8rt.':'Hoppet over er registrert. Ingen kilometer er lagt til.');
}
function openReview(){if(!state.plan)return;const w=state.plan.weeks[weekIndex],r=E.review(state.plan,state.logs,weekIndex);reviewContext={index:weekIndex,kind:r.kind};openModal(modalHead(r.title,`Uke ${weekIndex+1} \u00b7 ${shortDate(w.start)} \u2013 ${shortDate(w.end)}`)+`<div class="notice ${r.kind==='pause'||r.kind==='reduce'?'warn':''}">${esc(r.text)}</div>${w.adjustment?'<p class="subtle" style="margin-top:15px">Denne uken er allerede justert. Planen blir ikke redusert gjentatte ganger med samme datagrunnlag.</p>':''}<p class="tiny muted" style="margin-top:15px">Ukesjekken er en regelbasert hjelp. Den vurderer ikke skaderisiko eller helsetilstand, og gir ikke automatisk gr\u00f8nt lys for \u00e5 l\u00f8pe.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Behold uken</button>${r.canApply&&!w.adjustment?`<button class="btn" id="apply-review">${r.kind==='pause'?'Sett uken p\u00e5 pause':'Godkjenn roligere uke'}</button>`:''}</div>`);if($('#apply-review'))$('#apply-review').addEventListener('click',()=>{try{state.plan.weeks[reviewContext.index]=E.adjustWeek(w,reviewContext.kind);persist();closeModal();render();toast('Endringen er lagret. Historikken er ur\u00f8rt.');}catch(e){toast(e.message);}});}
function download(filename,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportBackup(){download('terskel-sikkerhetskopi-'+E.today()+'.json',JSON.stringify(state,null,2),'application/json;charset=utf-8');toast('Sikkerhetskopien inneholder profil, plan og logg. Oppbevar den privat.');}
function validateImport(o){
 const fail=()=>{throw new Error('Filen er ikke en gyldig Terskel-sikkerhetskopi (versjon 1).');};
 if(!o||o.version!==1||typeof o.profile!=='object'||!Array.isArray(o.logs)||o.logs.length>20000)fail();
 if(typeof o.profile.name!=='string'||o.profile.name.length>40||!Array.isArray(o.profile.days))fail();
 if(o.plan){
  if(typeof o.plan.id!=='string'||!o.plan.profile||!Array.isArray(o.plan.weeks)||o.plan.weeks.length<1||o.plan.weeks.length>27||!o.plan.speeds)fail();
  if(E.validate(o.plan.profile,o.plan.profile.startDate).length)fail();
  if(!Object.values(o.plan.speeds).every(v=>typeof v==='boolean'||(typeof v==='number'&&Number.isFinite(v))||v===null))fail();
  o.plan.weeks.forEach(w=>{
   if(!E.validDate(w.start)||!E.validDate(w.end)||!Array.isArray(w.sessions)||w.sessions.length>7||!Number.isFinite(w.km))fail();
   w.sessions.forEach(s=>{if(typeof s.id!=='string'||s.id.length>200||!E.validDate(s.date)||typeof s.title!=='string'||s.title.length>300||!Object.keys(TYPES).includes(s.type)||!Number.isFinite(s.km)||s.km<0||s.km>250||!Number.isFinite(s.minutes)||s.minutes<0||s.minutes>5000)fail();if(s.type==='threshold'&&(!Number.isFinite(s.reps)||!Number.isFinite(s.repMinutes)||!Number.isFinite(s.restSeconds)))fail();});
  });
 }
 for(const l of o.logs){
  if(!l||typeof l.id!=='string'||l.id.length>200||!E.validDate(l.date)||!['done','skipped'].includes(l.status)||!['easy','long','threshold','race'].includes(l.type)||!Number.isFinite(l.km)||l.km<0||l.km>200||!Number.isFinite(l.seconds)||l.seconds<0||l.seconds>86400||!Number.isFinite(l.rpe)||l.rpe<0||l.rpe>10||typeof l.note!=='string'||l.note.length>2000||!Object.keys(FEELINGS).includes(l.feeling)||typeof l.createdAt!=='string'||!Array.isArray(l.samples)||l.samples.length>40)fail();
  for(const s of l.samples){if(!s||!Number.isInteger(s.rep)||s.rep<1||s.rep>200||!(s.lactate===null||(Number.isFinite(s.lactate)&&s.lactate>=0&&s.lactate<=30))||!(s.hr===null||(Number.isFinite(s.hr)&&s.hr>=30&&s.hr<=240))||typeof s.pace!=='string'||s.pace.length>6)fail();}
 }
 return true;
}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('Filen er for stor. Maksimal st\u00f8rrelse er 5 MB.');return;}try{const parsed=JSON.parse(await file.text());validateImport(parsed);confirmDialog('Gjenopprette sikkerhetskopien?',`Dette erstatter den lokale profilen, planen og loggen med ${parsed.logs.length} registreringer fra filen. Eksporter f\u00f8rst dersom dagens data skal bevares.`,'Gjenopprett',()=>{state=parsed;persist();weekIndex=0;navigate(state.plan?'plan':'setup');toast('Sikkerhetskopien er gjenopprettet.');});}catch(error){toast(error.message||'Filen kunne ikke leses. Ingen data er endret.');}});
$('#activity-file').addEventListener('change',async e=>{const files=Array.from(e.target.files||[]);e.target.value='';if(!files.length)return;try{const result=await importActivities(files);const form=$('#setup-form');if(!form){toast('G\u00e5 til M\u00e5l & oppsett f\u00f8r du importerer treningsdata.');return;}form.elements.importedThresholdPace.value=result.pace;form.elements.importedActivityCount.value=String(result.count);form.elements.importedThresholdConfidence.value=result.confidence;form.elements.importedThresholdNote.value=result.note;const importedRadio=form.querySelector('input[name=\"thresholdSource\"][value=\"imported\"]');importedRadio.disabled=false;importedRadio.checked=true;updatePreview();toast(`Analysert ${result.read} fil${result.read===1?'':'er'}. Foresl\u00e5tt terskelfart: ${result.pace}/km.`);}catch(error){toast(error.message||'Aktivitetsdataene kunne ikke analyseres.');}});

function calendarExport(){
 if(!state.plan)return;const w=state.plan.weeks[weekIndex],events=w.sessions.filter(s=>s.type!=='rest');
 if(!events.length){toast('Ingen planlagte l\u00f8pe\u00f8kter \u00e5 eksportere denne uken.');return;}
 const clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
 const p=state.plan.profile;const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Terskel//Lopetrening v1//NB','CALSCALE:GREGORIAN','METHOD:PUBLISH',...events.flatMap(s=>{const easy=s.type==='easy'||s.type==='long',pulse=pulseGuidance(s,p);return ['BEGIN:VEVENT','UID:'+s.id+'@terskel.local','DTSTAMP:'+stamp,'DTSTART;VALUE=DATE:'+s.date.replace(/-/g,''),'DTEND;VALUE=DATE:'+E.addDays(s.date,1).replace(/-/g,''),'SUMMARY:'+clean('Terskel: '+s.title),'DESCRIPTION:'+clean(`PLANLAGT, ikke logget. ${easy?num(s.minutes)+' min (ca. '+num(s.km)+' km)': 'Ca. '+num(s.km)+' km / '+num(s.minutes)+' min'}. ${pulse?pulse+'. ':''}${s.type==='threshold'?s.warmMinutes+' min oppvarming; '+s.reps+' x '+s.repMinutes+' min med '+s.restSeconds+' sek pause; '+s.coolMinutes+' min nedjogg. ':''}${s.intensity} ${easy?'Tid og lett innsats styrer; fart tilpasses dagsform.':'Fart er bare veiledende.'}`),'STATUS:TENTATIVE','TRANSP:TRANSPARENT','END:VEVENT'];}),'END:VCALENDAR'];
 // RFC 5545 folding: at most 75 UTF-8 octets per line, no split code points.
 const folded=lines.map(line=>{let out='',current='',bytes=0;for(const c of line){const n=new TextEncoder().encode(c).length;if(bytes+n>74){out+=current+'\r\n';current=' ';bytes=1;}current+=c;bytes+=n;}return out+current;}).join('\r\n')+'\r\n';
 download(`terskel-uke-${weekIndex+1}.ics`,folded,'text/calendar;charset=utf-8');toast('Den valgte uken er eksportert som heldagshendelser. Import oppdaterer ikke kalenderen automatisk senere.');
}
document.addEventListener('click',e=>{
 const page=e.target.closest('[data-page]');if(page){navigate(page.dataset.page);return;}
 const ws=e.target.closest('[data-week]');if(ws){weekIndex=Number(ws.dataset.week);navigate('plan');return;}
 const ses=e.target.closest('[data-session]');if(ses){openSession(ses.dataset.session);return;}
 const edit=e.target.closest('[data-edit-log]');if(edit){openLog(edit.dataset.editLog);return;}
 const del=e.target.closest('[data-delete-log]');if(del){const l=state.logs.find(l=>l.id===del.dataset.deleteLog);if(l)confirmDialog('Slette registreringen?',`${longDate(l.date)}: ${TYPES[l.type]}. Dette kan ikke angres uten en sikkerhetskopi.`,'Slett',()=>{state.logs=state.logs.filter(x=>x.id!==l.id);persist();render();toast('Registreringen er slettet.');});return;}
 const remove=e.target.closest('.remove-sample');if(remove){remove.closest('.sample-row').remove();return;}
 const a=e.target.closest('[data-action]');if(!a)return;
 switch(a.dataset.action){case 'new-log':openLog();break;case 'close-modal':closeModal();break;case 'week-prev':weekIndex--;render();break;case 'week-next':weekIndex++;render();break;case 'export':exportBackup();break;case 'import':$('#import-file').click();break;case 'activity-import':$('#activity-file').click();break;case 'strava-info':openStravaInfo();break;case 'review':openReview();break;case 'calendar-export':calendarExport();break;}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
